    // Get the vertices of the edge and the neighbor
    int[] verticesOfE = graph.getVertices(e);
    int[] verticesOfN = graph.getVertices(n);

    // Find the vertices that are not in both e and n
    Set<Integer> verticesNotInEandN = new HashSet<>(Arrays.asList(verticesOfE));
